mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.3) * p.xz;
  float d = 100.0;
  for (int i = 0; i < 5; i++) {
    float s = 1.25 - float(i) * 0.22;
    vec3 a = abs(p) - vec3(s, s * 0.8, s);
    float box = max(a.x, max(a.y, a.z));
    float h = max(abs(p.x) - s * 0.85, max(abs(p.y) - s * 0.65, abs(p.z) - s * 0.85));
    d = min(d, max(box, -h));
  }
  return d;
}
