  vec3 ro = vec3(0.0, 0.0, -3.2);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.75;
  }
  vec3 col = vec3(0.02, 0.01, 0.04);
  if (t < 7.0) {
    vec3 pos = ro + rd * t;
    vec3 irid = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + (pos.x + pos.y + pos.z) * 6.0 + time);
    col = irid * 1.5;
  }
  col += glow * (0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + time * 1.5)) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
